from __future__ import annotations

import logging
import os
import pathlib
import re
import shutil
from collections import defaultdict
from collections.abc import Generator, Iterator
from ipaddress import IPv4Address, IPv4Network, IPv6Address, IPv6Network
from itertools import chain
from typing import Mapping, Optional, Sequence

import xmltodict

from taf.ul.ue.sim.env_setup.settings import CUSTOM_CONFIG

RE_IPADDR_V4_MO = re.compile(r"IPIF-\d+/(IPADDRESSV4-\d+)$")
RE_IPADDR_V6_MO = re.compile(r"IPIF-(\d+)/IPADDRESSV6-\d+$")
RE_IPV6_LOCAL = re.compile(r"inet6 (?P<ip>[\w:]+)/(?P<mask>\d+)")
RE_IPV4_LOCAL = re.compile(r"inet (?P<ip>[\d.]+)/(?P<mask>\d+)")
VLANIF_REGEX = re.compile(r"VLANIF-\d+$")
RMOD_REGEX = re.compile(r"MRBTS-\d+/EQM-\d+/APEQM-\d+/RMOD-\d+$")


def find_commissioning_filepath(scfc_name: str, enb_sw_release: str, suite_config_dir: str, logger: logging.Logger) -> str:
    """
    Finds the proper SCFC file inside directory. If SCFC for release is available then it will be provided.
    Otherwise, generic SCFC will be provided. Exception is raised if there is no file with corresponding name.

    :param str scfc_name: Name of SCFC to be found.
    :param str enb_sw_release: Name of BTS SW release that is installed.
    :param str suite_config_dir: Path to directory in which lookup for SCFC should be made.
    :param `logging.Logger` logger: Logger which saves the information.
    :return: Path to SCFC that should be used.
    :rtype: str
    :raises: :class:`Exception` if SCFC is not found
    """
    result = (
        _scf_fp_with_release(scfc_name, enb_sw_release, suite_config_dir, logger)
        or _scf_fp_without_release(scfc_name, suite_config_dir, logger)
        or _scf_fp_from_custom_config(scfc_name, logger)
    )
    assert result, f"Given SCFC file not found ({scfc_name})"
    logger.debug(f"SCFC found: {result}")
    return result


def _scf_fp_from_custom_config(scfc_name: str, logger: logging.Logger) -> Optional[str]:
    fp = CUSTOM_CONFIG.joinpath(scfc_name)
    logger.debug(f"Checking SCFC filepath with custom-config = {fp}")
    if fp.exists():
        return fp.as_posix()
    return None


def _scf_fp_with_release(scfc_name: str, enb_sw_release: str, suite_config_dir: str, logger: logging.Logger) -> Optional[str]:
    fp = pathlib.Path(suite_config_dir, enb_sw_release, scfc_name)
    logger.debug(f"Checking SCFC filepath with release. Path: {fp}")
    if fp.exists():
        return fp.as_posix()
    return None


def _scf_fp_without_release(scfc_name: str, suite_config_dir: str, logger: logging.Logger) -> Optional[str]:
    for scfc_dir_path in get_common_scfc_dirs(suite_config_dir, logger):
        fp = scfc_dir_path.joinpath(scfc_name.strip())
        logger.debug(f"Checking SCFC filepath without release = {fp}")
        if fp.exists():
            return fp.as_posix()
    return None


def get_common_scfc_dirs(config_path: str, logger: logging.Logger) -> Iterator[pathlib.Path]:
    all_dirs = sorted(
        [
            directory
            for directory in pathlib.Path(config_path).iterdir()
            if directory.is_dir() and directory.stem.upper().startswith(("SBTS", "FL", "TL"))
        ]
    )
    logger.debug(f"All dirs inside config: {all_dirs}")
    yield from all_dirs


def get_dict_from_xml(xml: pathlib.Path) -> dict:
    assert xml.exists(), f"XML file does not exist: {xml}"
    return xmltodict.parse(xml.read_text())


def save_dict_to_xml(_dict: dict, path: pathlib.Path) -> None:
    with path.open("w") as stream:
        stream.write(xmltodict.unparse(input_dict=_dict, pretty=True))


def _get_ip_addr_from_ipaddr_moc(ipaddr_mo: dict) -> str:
    for param in ipaddr_mo["p"]:
        if param["@name"] == "localIpAddr":
            return param["#text"]
    raise Exception("MOC 'IPIF/IPADDR' does not have 'localIpAddr'")


def _get_ip_addr(scfc_data: dict, regex: re.Pattern, ip_ver: int) -> dict[str, list[IPv4Address | IPv6Address]]:
    ip_addresses: dict[str, list[IPv4Address | IPv6Address]] = defaultdict(list)
    ipaddr_func: type[IPv4Address] | type[IPv6Address] = IPv4Address if ip_ver == 4 else IPv6Address
    for ipaddr_mo in scfc_data["raml"]["cmData"]["managedObject"]:
        dist_name = ipaddr_mo["@distName"]
        ipaddr_match = regex.search(dist_name)
        if ipaddr_match:
            suffix = "/" + ipaddr_match.group(1)
            ip_addresses[dist_name[: -len(suffix)]].append(ipaddr_func(_get_ip_addr_from_ipaddr_moc(ipaddr_mo)))
    return ip_addresses


def get_ipv4_bts_data(scfc_data: dict) -> Mapping[str, Sequence[IPv4Address | IPv6Address]]:
    return _get_ip_addr(scfc_data, RE_IPADDR_V4_MO, ip_ver=4)


def get_ipv6_bts_data(scfc_data: dict) -> Mapping[str, Sequence[IPv4Address | IPv6Address]]:
    return _get_ip_addr(scfc_data, RE_IPADDR_V6_MO, ip_ver=6)


def get_proper_eth3_name():
    cmd_output = os.popen("ip a list eth3").read().strip()

    if "master" in cmd_output:
        index = cmd_output.index("master")
        return cmd_output[index + 1]
    return "eth3"


def _get_local_ip_networks(regex: re.Pattern, ip_ver: int) -> list:
    eth3_data = os.popen(f"ip addr list {get_proper_eth3_name()}").read()
    ip_network_func, mask = (IPv4Network, "32") if ip_ver == 4 else (IPv6Network, "128")  # type
    return [ip_network_func("{}/{}".format(*match.groups()), strict=False) for match in regex.finditer(eth3_data) if match.group("mask") != mask]


def get_ipv6_local_networks() -> Sequence[IPv6Network]:
    return _get_local_ip_networks(RE_IPV6_LOCAL, 6)


def get_ipv4_local_networks() -> Sequence[IPv4Network]:
    return _get_local_ip_networks(RE_IPV4_LOCAL, 4)


def get_rel_version(scfc_data: dict) -> str:
    for mo in scfc_data["raml"]["cmData"]["managedObject"]:
        if RE_IPADDR_V4_MO.search(mo["@distName"]):
            return mo["@version"]
    raise Exception("Couldn't get release from any MOC in SCFC")


def create_new_vlan_mo(vlanifs_to_create: list[str], vlan_id: str, scfc_data: dict) -> None:
    version = get_rel_version(scfc_data)
    vlan_obj = {
        "@class": "com.nokia.srbts.tnl:VLANIF",
        "@distName": "",
        "@operation": "create",
        "@version": version,
        "p": {"#text": str(vlan_id), "@name": "vlanId"},
    }
    for vlanif in vlanifs_to_create:
        tmp_vlan_obj = vlan_obj.copy()
        tmp_vlan_obj["@distName"] = vlanif
        scfc_data["raml"]["cmData"]["managedObject"].append(tmp_vlan_obj)


def modify_existing_vlan_mo(vlanifs_to_modify: list[str], vlan_id: str, scfc_data: dict) -> None:
    vlanifs_mo = [_ for _ in scfc_data["raml"]["cmData"]["managedObject"] if VLANIF_REGEX.search(_["@distName"])]
    for vlanif in vlanifs_to_modify:
        for vlanif_mo in vlanifs_mo:
            if vlanif_mo["@distName"] == vlanif:
                if isinstance(vlanif_mo["p"], list):
                    for p in vlanif_mo["p"]:
                        if p["@name"] == "vlanId":
                            p["#text"] = str(vlan_id)
                else:
                    vlanif_mo["p"]["#text"] = str(vlan_id)


def get_ipifs_to_modify(
    gnb_data: Mapping[str, Sequence[IPv4Address | IPv6Address]], eth3_nets: Sequence[IPv4Network | IPv6Network]
) -> Generator[str, None, None]:
    return (ipif for ipif, ips in gnb_data.items() if any(ip in net for ip in ips for net in eth3_nets))


def get_vlanifs(
    ipifs_v4_to_modify: Generator[str, None, None],
    ipifs_v6_to_modify: Generator[str, None, None],
    scfc_data: dict,
) -> tuple[list[str], list[str]]:
    vlanifs_to_create = []
    vlanifs_to_modify = []
    for ipif in chain(ipifs_v4_to_modify, ipifs_v6_to_modify):
        for mo in (_ for _ in scfc_data["raml"]["cmData"]["managedObject"] if _["@distName"] == ipif):
            for param in mo["p"]:
                if param["@name"] == "interfaceDN":
                    if "VLANIF" not in param["#text"]:
                        param["#text"] += "/VLANIF-1"
                        vlanifs_to_create.append(param["#text"])
                    else:
                        vlanifs_to_modify.append(param["#text"])
    return vlanifs_to_create, vlanifs_to_modify


def check_and_remove_existing_vlans(vlanifs_to_create: list[str], scfc_data: dict, logger: logging.Logger) -> None:
    vlanifs_to_remove = []
    for vlanif in vlanifs_to_create:
        for idx, mo in enumerate(scfc_data["raml"]["cmData"]["managedObject"]):
            if mo["@distName"] == vlanif:
                logger.debug(f"VLANIF {vlanif} already exists in SCFC")
                vlanifs_to_remove.append((vlanif, idx))
    for vlanif, idx in vlanifs_to_remove:
        try:
            scfc_data["raml"]["cmData"]["managedObject"].pop(idx)
        except Exception as err:
            logger.error(f"Error while removing VLANIF {vlanif} from SCFC: {err}")


def get_rmods_num(scfc_data: dict, logger: logging.Logger) -> int:
    rmods = set()
    for mo in scfc_data["raml"]["cmData"]["managedObject"]:
        dist_name = mo["@distName"]
        if RMOD_REGEX.match(dist_name):
            logger.info(f"Found RMOD: {dist_name}")
            rmods.add(dist_name)
    return len(rmods)


def copy_scfc_to_output_dir(scfc_path: str | pathlib.Path, output_dir: str | pathlib.Path) -> pathlib.Path:
    if isinstance(scfc_path, str):
        scfc_path = pathlib.Path(scfc_path)
    if isinstance(output_dir, str):
        output_dir = pathlib.Path(output_dir)
    output_dir.mkdir(parents=True, exist_ok=True)
    output_path = output_dir.joinpath(scfc_path.name)
    shutil.copy(scfc_path, output_path)
    assert output_path.exists(), f"SCFC file not copied to output directory: {output_path}"
    return output_path
